import { EventEmitter } from 'eventemitter3';
import { InvalidMemberOfLinkedListException } from './invalid-list-node-exception';
import { LinkedListNode } from './linked-list-node';
import { LinkedListNodePool } from './linked-list-node-pool';
import { PooledMemberOfLinkedListException } from './pooled-list-node-exception';

interface LinkedListEvents<T> {
    nodeAdded: (node: LinkedListNode<T>) => void;
    nodeRemoved: (data: T) => void;
}

export class LinkedList<T extends object> extends EventEmitter<LinkedListEvents<T>> {
    public head?: LinkedListNode<T>;

    public tail?: LinkedListNode<T>;

    private linkedListNodePool: LinkedListNodePool<T>;

    constructor() {
        super();
        this.linkedListNodePool = new LinkedListNodePool<T>();
    }

    get empty(): boolean {
        return this.head === void 0;
    }

    public addLast(newNodeData: T): LinkedListNode<T> {
        const newNode: LinkedListNode<T> = this.linkedListNodePool.getNodeFromPool();
        newNode.data = newNodeData;

        if (this.tail) {
            this.tail.next = newNode;
            newNode.previous = this.tail;
        } else {
            this.head = newNode;
        }
        this.tail = newNode;

        this.emit('nodeAdded', newNode);
        return newNode;
    }

    public addFirst(newNodeData: T): LinkedListNode<T> {
        const newNode: LinkedListNode<T> = this.linkedListNodePool.getNodeFromPool();
        newNode.data = newNodeData;

        if (this.head) {
            this.head.previous = newNode;
            newNode.next = this.head;
        } else {
            this.tail = newNode;
        }
        this.head = newNode;

        this.emit('nodeAdded', newNode);
        return newNode;
    }

    public addAfter(newNodeData: T, newNodePrevious: LinkedListNode<T>): LinkedListNode<T> {
        if (newNodePrevious.data === void 0) {
            throw new PooledMemberOfLinkedListException();
        }

        if (!this.contains(newNodePrevious)) {
            throw new InvalidMemberOfLinkedListException();
        }

        const newNode: LinkedListNode<T> = this.linkedListNodePool.getNodeFromPool();
        newNode.data = newNodeData;

        if (this.tail === newNodePrevious) {
            this.tail = newNode;
        } else {
            newNode.next = newNodePrevious.next;
            newNode.next!.previous = newNode;
        }

        newNode.previous = newNodePrevious;
        newNodePrevious.next = newNode;

        this.emit('nodeAdded', newNode);
        return newNode;
    }

    public addBefore(newNodeData: T, newNodeNext: LinkedListNode<T>): LinkedListNode<T> {
        if (newNodeNext.data === void 0) {
            throw new PooledMemberOfLinkedListException();
        }
        if (!this.contains(newNodeNext)) {
            throw new InvalidMemberOfLinkedListException();
        }

        const newNode: LinkedListNode<T> = this.linkedListNodePool.getNodeFromPool();
        newNode.data = newNodeData;

        if (this.head === newNodeNext) {
            this.head = newNode;
        } else {
            newNode.previous = newNodeNext.previous;
            newNode.previous!.next = newNode;
        }

        newNode.next = newNodeNext;
        newNodeNext.previous = newNode;

        this.emit('nodeAdded', newNode);
        return newNode;
    }

    public remove(node: LinkedListNode<T>): T | undefined {
        if (this.contains(node)) {
            return this.removeNode(node);
        }
    }

    public removeAll(): void {
        while (this.head) {
            this.remove(this.head);
        }
    }

    public removeFirst(): T | undefined {
        if (this.head) {
            return this.removeNode(this.head);
        }
    }

    public removeLast(): T | undefined {
        if (this.tail) {
            return this.removeNode(this.tail);
        }
    }

    public contains(node: LinkedListNode<T>): boolean {
        let currentNode: LinkedListNode<T> | undefined = this.head;

        while (currentNode) {
            if (currentNode === node) {
                return true;
            }
            currentNode = currentNode.next;
        }
        return false;
    }

    private removeNode(node: LinkedListNode<T>): T {
        if (this.head === node) {
            this.head = this.head.next;
        }
        if (this.tail === node) {
            this.tail = this.tail.previous;
        }
        if (node.previous) {
            node.previous.next = node.next;
        }
        if (node.next) {
            node.next.previous = node.previous;
        }
        const nodeData: T = node.data!;

        node.next = void 0;
        node.previous = void 0;
        node.data = void 0;

        this.emit('nodeRemoved', nodeData);
        this.linkedListNodePool.addNodeToPool(node);

        return nodeData;
    }
}
